import os
import sys
import tempfile

sys.dont_write_bytecode = True

import numpy as np

_CACHE = tempfile.TemporaryDirectory(prefix="eval-mplcache-")
os.environ["MPLCONFIGDIR"] = _CACHE.name

import importlib.util

import matplotlib

matplotlib.use("Agg")

FAILS = []


def fail(msg):
    FAILS.append(msg)
    print("FAIL: " + msg)


def colorbars(fig):
    found = list(getattr(fig, "_colorbars", []) or [])
    for a in fig.axes:
        cb = getattr(a, "_colorbar", None)
        if cb is not None and cb not in found:
            found.append(cb)
    return found


values = np.array(
    [
        [-2.0, -0.5, 0.2],
        [-1.1, np.nan, 1.8],
        [0.0, 0.7, 3.0],
    ]
)
original = values.copy()

spec = importlib.util.spec_from_file_location("plot_mod", "plot.py")
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)
fn = getattr(mod, "make_figure", None)
if fn is None:
    fail("plot.py does not define make_figure(values)")
    sys.exit(1)

res = fn(values)
if not isinstance(res, (tuple, list)) or len(res) != 2:
    fail("make_figure must return (fig, ax)")
    sys.exit(1)
fig, ax = res

if not np.array_equal(values, original, equal_nan=True):
    fail("input array was modified by make_figure")

artists = list(ax.get_images())
artists.extend(c for c in ax.collections if getattr(c, "get_array", None) is not None and c.get_array() is not None)
if not artists:
    fail("no image or pcolormesh artist on the returned axes")
    sys.exit(1)

centered = False
missing_kept = False
distinct = False
for art in artists:
    norm = art.norm
    cmap = art.cmap
    try:
        t0 = float(norm(0.0))
    except Exception:
        t0 = None
    ramp = cmap(np.linspace(0.0, 1.0, 256))
    if t0 is not None:
        if abs(t0 - 0.5) <= 1e-6:
            centered = True
        chroma = ramp[:, :3].max(axis=1) - ramp[:, :3].min(axis=1)
        neutral = ramp[int(np.argmin(chroma)), :3]
        if float(np.abs(cmap(t0)[:3] - neutral).max()) <= 0.02:
            centered = True
    arr = np.ma.asarray(art.get_array())
    masked = np.count_nonzero(np.ma.getmaskarray(arr)) if np.ma.isMaskedArray(arr) else 0
    try:
        nan = int(np.isnan(np.ma.filled(arr.astype(float), np.nan)).sum())
    except Exception:
        nan = 0
    if masked or nan:
        missing_kept = True
    bad = cmap(np.ma.masked_array([0.0], mask=[True]))[0]
    if bad[3] == 0:
        distinct = True
    elif not np.any(np.all(np.abs(ramp[:, :3] - bad[:3]) < 0.02, axis=1)):
        distinct = True

if not centered:
    fail("colour scale is not centred on zero")
if not missing_kept:
    fail("unmeasured cell is not kept as missing in the drawn data (zero-filled?)")
if not distinct:
    fail("missing cells use a colour indistinguishable from the scale")

cbs = colorbars(fig)
if not cbs:
    fail("no colourbar")
else:
    label = ""
    for cb in cbs:
        text = cb.ax.get_ylabel() or cb.ax.get_xlabel()
        if not text and getattr(cb, "label", None) is not None:
            text = cb.label.get_text()
        label = (text or "").strip() or label
    if not label:
        fail("colourbar has no label")

if FAILS:
    sys.exit(1)
print("PASS: centred scale, missing cells distinct and kept, labelled colourbar, input untouched")
PYEOF_HARNESS
